package com.nigson.integration.carrier;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.Problem;
import static org.assertj.core.api.Assertions.*;
class CarrierTrackingValuesTest {
 static final Instant NOW=Instant.parse("2026-10-15T12:00:00Z");static final String ID="123456789012";
 static ObjectNode output(String id,String code,Instant at){return (ObjectNode)EventCodec.JSON.valueToTree(Map.of("completeTrackResults",List.of(Map.of("trackingNumber",id,"trackResults",List.of(Map.of("trackingNumberInfo",Map.of("trackingNumber",id),"latestStatusDetail",Map.of("code",code),"scanEvents",List.of(Map.of("eventType",code,"date",at.toString())),"dateAndTimes",List.of(Map.of("type","ACTUAL_DELIVERY","dateTime",at.toString()))))))));}
 @Test void usesProviderTimestampAndRequiresActualDelivery(){var parsed=CarrierTrackingValues.parse(output(ID,"DL",NOW.minusSeconds(60)),List.of(ID),NOW);assertThat(CarrierTrackingValues.aggregate(parsed,1)).isEqualTo(new CarrierTrackingValues.Observation("DELIVERED",NOW.minusSeconds(60)));var broken=output(ID,"DL",NOW);((ObjectNode)broken.path("completeTrackResults").path(0).path("trackResults").path(0)).remove("dateAndTimes");assertThatThrownBy(()->CarrierTrackingValues.parse(broken,List.of(ID),NOW)).isInstanceOf(Problem.Failure.class);}
 @Test void missingForeignAndDuplicateCoverageNeverProducesPartialTruth(){assertThatThrownBy(()->CarrierTrackingValues.parse(output(ID,"IT",NOW),List.of(ID,"123456789013"),NOW)).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->CarrierTrackingValues.parse(output(ID,"IT",NOW),List.of("123456789013"),NOW)).isInstanceOf(Problem.Failure.class);var duplicate=output(ID,"IT",NOW);((tools.jackson.databind.node.ArrayNode)duplicate.path("completeTrackResults")).add(duplicate.path("completeTrackResults").path(0));assertThatThrownBy(()->CarrierTrackingValues.parse(duplicate,List.of(ID,"123456789013"),NOW)).isInstanceOf(Problem.Failure.class);}
 @Test void unknownCodeMalformedTimestampFutureAndErrorFailClosed(){for(String code:List.of("pending","UNKNOWN"))assertThatThrownBy(()->CarrierTrackingValues.parse(output(ID,code,NOW),List.of(ID),NOW)).isInstanceOf(Problem.Failure.class);assertThatThrownBy(()->CarrierTrackingValues.parse(output(ID,"IT",NOW.plusSeconds(6)),List.of(ID),NOW)).isInstanceOf(Problem.Failure.class);var broken=output(ID,"IT",NOW);var result=(ObjectNode)broken.path("completeTrackResults").path(0).path("trackResults").path(0);result.put("error","synthetic");assertThatThrownBy(()->CarrierTrackingValues.parse(broken,List.of(ID),NOW)).isInstanceOf(Problem.Failure.class);result.remove("error");((ObjectNode)result.path("scanEvents").path(0)).put("date","invalid");assertThatThrownBy(()->CarrierTrackingValues.parse(broken,List.of(ID),NOW)).isInstanceOf(Problem.Failure.class);}
 @Test void allPiecesMustReachTerminalAndExceptionsUseTheirOwnTimestamp(){var delivered=new CarrierTrackingValues.Scan(ID,"DL",NOW);var transit=new CarrierTrackingValues.Scan("123456789013","IT",NOW.minusSeconds(10));var cancelled=new CarrierTrackingValues.Scan("123456789014","CA",NOW.minusSeconds(20));assertThat(CarrierTrackingValues.aggregate(List.of(delivered,transit),2).status()).isEqualTo("SHIPPED");assertThat(CarrierTrackingValues.aggregate(List.of(delivered,cancelled),2)).isEqualTo(new CarrierTrackingValues.Observation("EXCEPTION",NOW.minusSeconds(20)));assertThat(CarrierTrackingValues.aggregate(List.of(new CarrierTrackingValues.Scan(ID,"OC",NOW)),1).status()).isNull();assertThatThrownBy(()->CarrierTrackingValues.aggregate(List.of(delivered,delivered),2)).isInstanceOf(Problem.Failure.class);}
 @Test void matchingScanIsRequiredAndScanOrderDoesNotChangeLatest(){var missing=output(ID,"IT",NOW);var events=(tools.jackson.databind.node.ArrayNode)missing.path("completeTrackResults").path(0).path("trackResults").path(0).path("scanEvents");((ObjectNode)events.path(0)).put("eventType","OC");assertThatThrownBy(()->CarrierTrackingValues.parse(missing,List.of(ID),NOW)).isInstanceOf(Problem.Failure.class);events.add(EventCodec.JSON.valueToTree(Map.of("eventType","IT","date",NOW.minusSeconds(1).toString())));assertThat(CarrierTrackingValues.parse(missing,List.of(ID),NOW).getFirst().occurredAt()).isEqualTo(NOW.minusSeconds(1));}
}
